Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='filesasthemselves', at=datetime(2026, 9, 29, 0, 0, 0), actor='assistant', title='A PDF or an image reaches the model as itself, unless its text names an ID number', body="Since 2026-09-29 a PDF or an image reaches the model AS ITSELF (`suzatary_core::file_read`, the `email-attachments-jakuay` report): `FileRead::of` reads a PDF's text layer first and withholds any file whose text names one of those numbers, answering with the redacted text instead; a scan's pixels cannot be redacted, and are handed over as they are.", rationale='Decided 2026-09-29 (the email-attachments-jakuay report).', supersedes=()))